["import json

text = """
On February 21 , Broadcom reduced their offer to $117 billion in light of Qualcomms increased bid for NXP Semconductors. The deal was effectively blocked after US President Donald Trump blocked any deal based upon national security grounds .
"""

# Parse the text into a JSON object
data = json.loads(text)

# Extract entities from the text
entities = {
    "Company": [data["text"].split(" Broadcom")[0], data["text"].split("Qualcomms")[0], data["text"].split("NXP Semconductors")[0], data["text"].split("US President Donald Trump")[0]],
    "Date": [data["text"].split("February 21")[0], data["text"].split("The deal were effectively blocked")[0], data["text"].split("after US President Donald Trump")[0], data["text"].split("based upon national security grounds")[0]],
    "Location": [data["text"].split(" Broadcom")[1], data["text"].split("Qualcomms")[1], data["text"].split("NXP Semconductors")[1], data["text"].split("US President Donald Trump")[1]],
    "Money": [data["text"].split("$117 billion")[0], data["text"].split("The deal were effectively blocked")[0], data["text"].split("after US President Donald Trump")[0], data["text"].split("based upon national security grounds")[0]],
    "Person": [data["text"].split("US President Donald Trump")[1]],
    "Product": [data["text"].split("NXP Semconductors")[1]],
    "Quantity": [data["text"].split(" billion")[0]]
}

# Print the output fields
print(json.dumps(entities, indent=4))

# Check if the entities are completed
if len(entities["Company"]) > 0:
    completed = True
else:
    completed = False

if len(entities["Date"]) > 0:
    completed = True
else:
    completed = False

if len(entities["Location"]) > 0:
    completed = True
else:
    completed = False

if len(entities["Money"]) > 0:
    completed = True
else:
    completed = False

if len(entities["Person"]) > 0:
    completed = True
else:
    completed = False

if len(entities["Product"]) > 0:
    completed = True
else:
    completed = False

if len(entities["Quantity"]) > 0:
    completed = True
else:
    completed = False

if completed:
    print("[## completed ##]")
else:
    print("[## entities ##]")"]

["import json

text = """
With the re - negotiated lower price of $21.5 billion between Johnson & Johnson and Guidant , Boston Scientific announced an unsolicited offer of $24.6 billion for Guidant ( an offer of $72 per share of Guidant , $36 in cash and a fixed number of Boston Scientific shares valued at $36 a share ) .

"""

# Load the JSON schema
schema = '''
{
    "type": "object",
    "properties": {
        "entities": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "completed": {
            "type": "boolean"
        }
    },
    "required": ["entities", "completed"]
}
'''

# Load the JSON data
data = json.loads(text)

# Extract entities
entities = []
for category in data['entities']:
    for item in category['entities']:
        if item is None:
            continue
        entities.append(item)

# Print the output
print(json.dumps(data, indent=2))
print("[[ ## entities ## ]] =", entities)
print("[[ ## completed ## ]]")"]

