["import json

text = '''Xerox 's $33.5 billion ( 25.8 billion ) cash - and - stock offer to buy bigger rival HP was declined , with HP indicating it might make its own counter - offer for Xerox .'''

data = json.loads(text)

entities = []
for key, value in data.items():
    if key == 'entities':
        for entity in value:
            if entity['type'] == 'string':
                entities.append(entity['value'])
    elif key == 'title':
        entities.append(value)
    elif key == 'description':
        entities.append(value)
    elif key == 'date':
        entities.append(value)
    elif key == 'location':
        entities.append(value)
    elif key == 'money':
        entities.append(value)
    elif key == 'person':
        entities.append(value)
    elif key == 'product':
        entities.append(value)
    elif key == 'quantity':
        entities.append(value)

print(json.dumps(data, indent=2))
print('[[ ## entities ## ]]')
print(json.dumps(entities, indent=2))
print('[[ ## completed ## ]]')"]

